extern Adafruit_SSD1306 display;

void applyRuns(const uint8_t* data, uint16_t len) {
 for (uint16_t i = 0; i + 2 < len; i += 3) {
uint8_t y = pgm_read_byte(&data[i]);
if (y == 255) {break;} // End of data marker
uint8_t startX = pgm_read_byte(&data[i + 1]);
uint8_t width = pgm_read_byte(&data[i + 2]);
display.drawFastHLine(startX, y, width, SSD1306_WHITE);
}
}

